-- Nexgen OS — country pack XA (Examplia), version 0.1.0.
--
-- Generated by `nexgen-os pack build xa` from packs/xa/: pack.json, identifiers.json, sources.json, project_kinds.json, municipalities.json, grid.json, defaults.json.
-- Do not edit: change the pack and build again. `nexgen-os pack check --all`
-- refuses a seed that is not the exact output of its pack.
--
-- file           supabase/seed/10_pack_xa.sql
-- checksum       sha256:9f5397c89743b5b411c128afe73047eb7a6964bea6b853192942f9ed43bb57a3
-- certification  reviewed, A grid engineer of the fixture, for the tests of the toolchain, 2026-10-19
-- schema_min     0.2.0
-- modules        grid
--
-- Every row is upserted by its natural key, so the file can be applied again
-- and a new version of the pack reaches an installation holding an older one.
-- A vocabulary row is updated only where this pack published it. A value is
-- dated and never edited: the database refuses a value that differs from the
-- one it holds for the same attribute type, region and valid_from (value_edited).
-- Nothing is deleted. Apply the file in one transaction, as the installer does.

set search_path = nexgen, extensions;

-- sources: 3. The registers, services and texts the country's data and values come from.
insert into sources (code, name, description, kind, base_url, docs_url, auth, countries, regions, license, attribution, retention_days, redistributable, published_by) values
  ('xa_address_register', 'Address register of the North', null, 'api', 'https://example.org/addresses', 'https://example.org/addresses/docs', 'none', array['XA']::text[], array['XA-N']::text[], 'CC-BY-4.0', 'Address register of the North', null, true, 'pack:xa'),
  ('xa_grid_code', 'Grid code of Examplia', null, 'text', 'https://example.org/grid-code', null, 'none', array['XA']::text[], '{}'::text[], 'public text', null, null, true, 'pack:xa'),
  ('xa_statistics', 'Statistics office of Examplia', null, 'file', 'https://example.org/statistics', null, 'none', array['XA']::text[], '{}'::text[], 'CC-BY-4.0', null, 30, false, 'pack:xa')
on conflict (code) do update set
  name            = excluded.name,
  description     = excluded.description,
  kind            = excluded.kind,
  base_url        = excluded.base_url,
  docs_url        = excluded.docs_url,
  auth            = excluded.auth,
  countries       = excluded.countries,
  regions         = excluded.regions,
  license         = excluded.license,
  attribution     = excluded.attribution,
  retention_days  = excluded.retention_days,
  redistributable = excluded.redistributable
where sources.published_by = excluded.published_by;

-- identifier_schemes: 2. The identifiers the country issues; a value of identifiers or meters matches the pattern.
insert into identifier_schemes (code, name, description, pattern, url_template, source_code, icd, published_by) values
  ('xa_metering_point', 'Metering point number', 'Issued by the distribution operator of the connection.', '^XA[0-9]{8}$', null, null, null, 'pack:xa'),
  ('xa_municipality', 'Municipality code', null, '^[0-9]{5}$', 'https://example.org/municipality/{value}', 'xa_statistics', null, 'pack:xa')
on conflict (code) do update set
  name         = excluded.name,
  description  = excluded.description,
  pattern      = excluded.pattern,
  url_template = excluded.url_template,
  source_code  = excluded.source_code,
  icd          = excluded.icd
where identifier_schemes.published_by = excluded.published_by;

-- currencies: the currency of the country, which the core's list does not hold. Never updated: the core and Ekwo OS keep one list.
insert into currencies (code, name, symbol, decimal_places) values ('XTS', 'Code reserved for testing', null, 0)
on conflict (code) do nothing;

-- countries: who the country is, and which version of its pack this installation holds.
insert into countries (code, name, currency, languages, time_zones, region_level, postal_code_pattern, municipality_scheme, bbox, pack_version, pack_checksum, published_by) values
  ('XA', 'Examplia', 'XTS', array['en']::text[], array['Etc/UTC', 'Etc/GMT-1']::text[], 'province', '^[0-9]{4}$', 'xa_municipality', null::double precision[], '0.1.0', 'sha256:9f5397c89743b5b411c128afe73047eb7a6964bea6b853192942f9ed43bb57a3', 'pack:xa')
on conflict (code) do update set
  name                = excluded.name,
  currency            = excluded.currency,
  languages           = excluded.languages,
  time_zones          = excluded.time_zones,
  region_level        = excluded.region_level,
  postal_code_pattern = excluded.postal_code_pattern,
  municipality_scheme = excluded.municipality_scheme,
  bbox                = excluded.bbox,
  pack_version        = excluded.pack_version,
  pack_checksum       = excluded.pack_checksum;

-- regions: 3 at the level province and above, parents first.
insert into regions (code, country, name, kind, parent, time_zone, names, aliases, postal_prefixes, published_by) values
  ('XA-N', 'XA', 'North', 'subdivision', null, null, '{}'::jsonb, '{}'::text[], '{}'::text[], 'pack:xa'),
  ('XA-S', 'XA', 'South', 'subdivision', null, 'Etc/GMT-1', '{}'::jsonb, '{}'::text[], '{}'::text[], 'pack:xa'),
  ('XA-NW', 'XA', 'North-West', 'subdivision', 'XA-N', null, '{}'::jsonb, '{}'::text[], '{}'::text[], 'pack:xa')
on conflict (code) do update set
  country         = excluded.country,
  name            = excluded.name,
  kind            = excluded.kind,
  parent          = excluded.parent,
  time_zone       = excluded.time_zone,
  names           = excluded.names,
  aliases         = excluded.aliases,
  postal_prefixes = excluded.postal_prefixes
where regions.published_by = excluded.published_by;

-- regions: 2 municipalities, each under its province, coded XA-<xa_municipality>.
insert into regions (code, country, name, kind, parent, published_by) values
  ('XA-20001', 'XA', 'Southport', 'municipality', 'XA-S', 'pack:xa'),
  ('XA-20002', 'XA', 'Dunmoor', 'municipality', 'XA-S', 'pack:xa')
on conflict (code) do update set
  country = excluded.country,
  name    = excluded.name,
  kind    = excluded.kind,
  parent  = excluded.parent
where regions.published_by = excluded.published_by;

-- project_kinds: 1. The frames of projects the law of the country defines, each refining a kind of the core.
insert into project_kinds (code, name, description, parent_code, country, source_code, reference, published_by) values
  ('xa_sharing', 'Energy sharing of Examplia', 'Neighbours sharing what some of them produce, within the perimeter of the grid code.', 'collective_self_consumption', 'XA', 'xa_grid_code', 'Article 30', 'pack:xa')
on conflict (code) do update set
  name        = excluded.name,
  description = excluded.description,
  parent_code = excluded.parent_code,
  country     = excluded.country,
  source_code = excluded.source_code,
  reference   = excluded.reference
where project_kinds.published_by = excluded.published_by;

-- grid.operators: 3. Who runs the grid, where, and which metering identifier they issue.
insert into grid.operators (code, name, kind, country, regions, municipalities, identifier_prefixes, coverage, website, data_hub_url, meter_data, identifier_scheme, eic_code, description, published_by) values
  ('xa_dunmoor_dso', 'Distribution operator of Dunmoor', 'dso', 'XA', '{}'::text[], array['XA-20002']::text[], '{}'::text[], null, null, null, '{}'::jsonb, null, null, null, 'pack:xa'),
  ('xa_north_dso', 'Distribution operator of the North', 'dso', 'XA', array['XA-N', 'XA-NW']::text[], '{}'::text[], array['XA1']::text[], null, null, 'https://example.org/north/hub', '{}'::jsonb, 'xa_metering_point', null, null, 'pack:xa'),
  ('xa_tso', 'Transmission operator of Examplia', 'tso', 'XA', '{}'::text[], '{}'::text[], '{}'::text[], null, 'https://example.org/tso', null, '{}'::jsonb, null, null, null, 'pack:xa')
on conflict (code) do update set
  name                = excluded.name,
  kind                = excluded.kind,
  country             = excluded.country,
  regions             = excluded.regions,
  municipalities      = excluded.municipalities,
  identifier_prefixes = excluded.identifier_prefixes,
  coverage            = excluded.coverage,
  website             = excluded.website,
  data_hub_url        = excluded.data_hub_url,
  meter_data          = excluded.meter_data,
  identifier_scheme   = excluded.identifier_scheme,
  eic_code            = excluded.eic_code,
  description         = excluded.description
where operators.published_by = excluded.published_by;

-- defaults: 10 value(s), 4 of them for a region or a municipality, 1 for a condition. What parameter_of() answers
-- for a participant of the country when nothing nearer gives a value.
do $seed$
declare
  refused text;
begin
  with pack (attribute_type, region, condition, value, unit, valid_from, valid_to, source_code, reference, quality) as (
    values
      ('connection_max_power_lv'::text, null::text, '{}'::jsonb, '250'::jsonb, 'KiloW'::text, '2020-01-01'::date, null::date, 'xa_grid_code'::text, 'Article 7, table 1'::text, 'published'::text),
      ('density_class'::text, 'XA-20001'::text, '{}'::jsonb, '"dense"'::jsonb, 'code'::text, '2026-01-01'::date, null::date, 'xa_statistics'::text, 'Density grid 2026'::text, 'published'::text),
      ('density_class'::text, 'XA-20002'::text, '{}'::jsonb, '"sparse"'::jsonb, 'code'::text, '2026-01-01'::date, null::date, 'xa_statistics'::text, 'Density grid 2026'::text, 'published'::text),
      ('grid_co2_factor'::text, null::text, '{}'::jsonb, '0.12'::jsonb, 'KiloGM-PER-KiloW-HR'::text, '2026-01-01'::date, null::date, 'xa_statistics'::text, 'Yearly balance 2025, table 3'::text, 'published'::text),
      ('metering_step'::text, null::text, '{}'::jsonb, '"PT30M"'::jsonb, 'ISO8601-duration'::text, '2020-01-01'::date, '2025-01-01'::date, 'xa_grid_code'::text, 'Article 12'::text, 'published'::text),
      ('metering_step'::text, null::text, '{}'::jsonb, '"PT15M"'::jsonb, 'ISO8601-duration'::text, '2025-01-01'::date, null::date, 'xa_grid_code'::text, 'Article 12, as amended'::text, 'published'::text),
      ('offpeak_hours'::text, null::text, '{}'::jsonb, null::jsonb, 'hours'::text, '2020-01-01'::date, null::date, 'xa_grid_code'::text, 'Article 40: set by each supply contract'::text, 'published'::text),
      ('sharing_max_distance_m'::text, 'XA-S'::text, '{"project_kind":"xa_sharing","density_class":"sparse"}'::jsonb, '10000'::jsonb, 'M'::text, '2023-07-01'::date, null::date, 'xa_grid_code'::text, 'Article 31, second paragraph'::text, 'published'::text),
      ('sharing_max_distance_m'::text, 'XA-S'::text, '{}'::jsonb, '2000'::jsonb, 'M'::text, '2023-07-01'::date, null::date, 'xa_grid_code'::text, 'Article 31'::text, 'published'::text),
      ('voltage_levels'::text, null::text, '{}'::jsonb, '[{"code":"lv","name":"Low voltage","min_kv":0,"max_kv":1},{"code":"mv","name":"Medium voltage","min_kv":1,"max_kv":36},{"code":"hv","name":"High voltage","min_kv":36,"max_kv":400}]'::jsonb, 'KiloV'::text, '2020-01-01'::date, null::date, 'xa_grid_code'::text, 'Article 2'::text, 'published'::text)
  ),
  problems (problem) as (
    select format('attribute_type_unknown: %s is not an attribute_types code', p.attribute_type)
      from pack p
     where not exists (select 1 from attribute_types d where d.code = p.attribute_type)
    union all
    select format('unit_mismatch: %s is stored in %s and the pack says %s', p.attribute_type, u.unit, p.unit)
      from pack p
      join attribute_types d on d.code = p.attribute_type
      join quantities q on q.code = d.quantity_code
      cross join lateral (select quantity_unit(q.code, (select c.currency from countries c where c.code = 'XA')) as unit) u
     where u.unit <> p.unit
    union all
    select format('value_edited: %s%s from %s holds %s and the pack says %s; close it with valid_to and add a row',
                  p.attribute_type, coalesce(' (' || nullif(concat_ws(', ', p.region, nullif(p.condition, '{}')::text), '') || ')', ''), p.valid_from,
                  coalesce(x.value::text, 'null'), coalesce(p.value::text, 'null'))
      from pack p
      join defaults x
        on x.country = 'XA' and x.attribute_type = p.attribute_type
       and x.region is not distinct from p.region and x.valid_from = p.valid_from
       and x.condition = p.condition
     where x.value is distinct from p.value
  ),
  written as (
    insert into defaults (attribute_type, country, region, condition, value, valid_from, valid_to,
                          source_code, reference, quality, published_by)
    select p.attribute_type, 'XA', p.region, p.condition, p.value, p.valid_from, p.valid_to,
           p.source_code, p.reference, p.quality, 'pack:xa'
      from pack p
     where not exists (select 1 from problems)
    on conflict (country, region, attribute_type, condition, valid_from) do update set
      valid_to    = excluded.valid_to,
      source_code = excluded.source_code,
      reference   = excluded.reference,
      quality     = excluded.quality
    returning 1
  )
  select string_agg(problem, '; ' order by problem) into refused from problems;
  if refused is not null then
    raise exception '%', refused;
  end if;
end
$seed$;
